import styled from '@emotion/styled';

export const StyledClearIndicator = styled.div({
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  borderRadius: '50%',
  backgroundColor: '#757575',
  color: '#ffffff',
  cursor: 'pointer',
  fontSize: '12px',
  width: '20px',
  height: '20px',
});
